import sys

def read_input():
    lines = sys.stdin.read().splitlines()
    n = int(lines[1])
    coordinates = [tuple(map(int, line.split())) for line in lines[2:2+n]]
    W, H = coordinates[0]
    m = int(lines[2+n])
    fills = [tuple(map(int, line.split())) for line in lines[2+n+1:2+n+1+m]]
    return W, H, n, coordinates, m, fills

def calculate_areas(W, H, coordinates, fills):
    area = 0
    color_map = {}
    for x1, y1, x2, y2 in coordinates:
        for x in range(x1, x2+1):
            for y in range(y1, y2+1):
                area += W * H
                color = chr(128 + y // W % 16)  # Convert y coordinate to color code
                if (x, y) in fills:
                    area -= 1  # Subtract the area occupied by the segment
                    color_map.setdefault(color, 0)
                    color_map[color] += 1
    return color_map

def print_areas(color_map):
    for color, area in sorted(color_map.items(), key=lambda item: -item[1]):
        print(f'{color} {area:.10f}')

def main():
    W, H, n, coordinates, m, fills = read_input()
    color_map = calculate_areas(W, H, coordinates, fills)
    print_areas(color_map)

if __name__ == '__main__':
    main()
