                dp_cache[n][k] = (dp_cache[n][k] + val) % MOD
        else:
            for i in dp_cache[n-1]:
                val = cache[i] * dp_cache[k][i] % MOD
                dp_cache[n][k] = (dp_cache[n][k] + val) % MOD

        return dp_cache[n][k]

    cache = [0 for _ in range(n)]
