def lexicographical_order(names):
    return "".join(sorted(names))

def main():
    n, m, k = map(int, input().split())
    s = input()
    meeting_rooms = [0] * m
    current_index = 0
    available_indices = set(range(n))

    while True:
        available_indices.discard(current_index)
        available_indices = available_indices - {i for i in range(len(s) - 1) if s[i] >= s[i + 1]}
        if len(available_indices) == 0:
            break
        available = sorted(available_indices, key=lambda x: s[x] - s[current_index])
        meeting_rooms[current_index % m] = available[0]
        available_indices.remove(available[0])
        next_index = available[0] + 1
        if next_index == n:
            break
        current_index += 1

    names = [s[max(meeting_rooms[i], i): min(meeting_rooms[i + 1], i + 1)] for i in range(m)]
    return lexicographical_order(names[k - 1])

print(main())
