def min_operations(arr):
    n = len(arr)
    operations = 0
    i = 0
    j = n - 1

    while i < j:
        if arr[i] >= arr[i + 1]:
            i += 1
        elif arr[j] <= arr[j - 1]:
            j -= 1
        else:
            operations += 2
            if arr[i] < arr[j]:
                i += 1
            elif arr[j] < arr[i]:
                j -= 1

