import math

def compute_damage(value):
    return value * value

def compute_rarity(value):
    return value * value

def compute_plus(value):
    return value / 10

def max_gold(enemy1_health, enemy2_health, enemy2_rarity, bonus):
    max_value = max(enemy1_health, enemy2_health)
    if max_value > enemy2_health:
        return bonus + max_value * compute_rarity(max_value)

def main():
    enemy_count = int(input().split()[0])
    update_count = int(input().split()[1])
    enemy_info = [list(map(int, input().split())) for _ in range(enemy_count)]
    battle_update = [list(map(int, input().split())) for _ in range(update_count)]

    enemy1_health, enemy2_health, enemy2_rarity = int(input().split()[0]), int(input().split()[0]), int(input().split()[0])
    enemy1_bounty, enemy2_bonus = int(input().split()[0]), int(input().split()[0])
    current_battle = [-1 * enemy1_bounty, enemy2_bonus]

    largest_rarity = 0

    for update in battle_update: # per turn
        character_value = current_battle[1] if update[0] >= current_battle[0] else current_battle[0]
        enemy_value = enemy_info[0][character_value]

        if update[1] == 1:
            enemy_value = max(update[2], enemy_value)
        else:
            attack_damage_mod = math.floor((update[2] - enemy_value) / compute_plus(enemy_value))
            enemy_value = min(update[2], enemy_value + attack_damage_mod * compute_plus(enemy_value))

        if enemy_value >= enemy1_health:
            current_battle[0] = min([enemy1_health, update[1] - enemy2_health])
            current_battle[1] = max(enemy1_bounty, enemy2_bonus - attack_damage_mod)
            if current_battle[0] == 0: # multiples of 1 your enemy vilified
                current_battle[1] += update[1] * (enemy2_rarity + compute_rarity(update[1])) - compute_plus(enemy2_rarity)
            else:
                current_battle[1] += (current_battle[0] - (update[1] - enemy2_health) - enemy2_bonus) * compute_plus(enemy2_value)

            enemy1_health, enemy2_health = max(enemy1_health - current_battle[0], 0), min(enemy2_health + current_battle[1], 0)
            enemy2_rarity = max(enemy2_rarity + compute_rarity(current_battle[1]), horizon_rarity(enemy2_rarity))

        largest_rarity = max(enemy2_rarity, largest_rarity)
    return -1

def horizon_rarity(current_rarity):
    return max([current_rarity + (math.floor((-10 + math.pow(2, int(math.log(abs(current_rarity) + 10) / 10)) / 10) * 0.998) / 1000), 0])

def penalty_harmonyリスク(current_battle):
    hp, bonus, bonus_cost, target_rarity = current_battle
    penalty = (target_rarity - 1)
    if hp != 0:
        penalty = max(penalty, bonus_cost - hp + hp / 10)
    return penalty

