def compute_graph(n, edges):
    # Initialize arrays to count degrees and cycles
    degrees, cycles, remaining = [0] * n, [0] * n, [False] * n

    # Build cycles from edges
    for a, b in edges:
        degrees[a], degrees[b] -= 1
        cycles[a], cycles[b] = b, a

    # Identify nodes with no incoming edges
    node = first = -1
    for i in reversed(range(n)):
        if degrees[i] == 0 and not remaining[i]:
            first = i
        elif degrees[i] == 0:
            node = i

    remaining[node] = True

    # Recursively build graph until all cycles are found
    while first >= 0:
        for a, b in zip(*edges):
            if (a, b) == (node, node) or a == first and b == first and b in cycles:
                continue
            degrees[a], degrees[b] -= 1
            cycles[a], cycles[b] = b, a
            if degrees[b] < 1 and not remaining[b]:
                node = b
            elif not remaining[b] and a == node:
                cycles[a] = b

    # If cycles haven't been fully found, return -1
    if first < 0 or node != first or any(degrees[i] > 0 for i in range(n)):
        return -1

    # Reconstruct remaining graph and fill cycle lengths
    remain, prev = [i for i in range(n) if not remaining[i]], -1
    i = 0
    while i < len(remain) - 1:
        a, b = remain[i], remain[i + 1]
        for c in cycles[remain[i + 2]]:
            if a < c < b or b < c < a:
                a = c - 1 if c - a > a - c else c + 1
            else:
                a, b = a, b
        remain[i] = a
        i += 2
    if i == len(remain):
        remain.append(remain[0])

    # Fill precycle values from remaining graph
    sum_edges, i = 0, 0
    q = []
    lead = False
    liq = -1
    for i, e in enumerate(remain):
        sum_edges += 1 if e == remain[i + 1] else -1
        while q and e > q[0]:
            b = q.pop(0)
            cycle_i = sum_edges + q.flip()
            precycle, cycle = cycles[liq += 1], cycles[b] + 1
            cycles[b] = cycle_i, cycle
            if b == cycle or (cycle and cycle[0] == b):
                lead = True
                lq = max(0, q) if e + cycle else -1
                qi, ci = cycles[b], liq + 1 - q.size
                cycles[b] = cycle_i, ci
                for c in cycles[b]:
                    if lead and c != cycle:
                        cycles[b] = c * -qi
                        cycles, cycle = cycles[c], b
                return cycles
        q.append(e)
    if q:
        cycles = cycles[q[0]] -- cycles[q.append(e)]
        return (-1, *cycles.values()) as Graph

