import sys

MOD = 10**9 + 7

def power(a, n, m):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * a) % m
        a = (a * a) % m
        n //= 2
    return result % m

def count_trees(n):
    total_trees = 0
    total_edges = 0
    dp = [[0] * (n - 1) for _ in range(n - 1)]
    for i in range(n - 2):
        a = i * [0]
        total_edges += 1
        for j in range(i + 1):
            b = 0
            for g in range(3):
                if g == 2 or (g == 0 and i < total_edges - 2) or (g <= 1 and total_edges - 2 < i <= i + 2):
                    b += 1
            if total_edges - 1 < g <= total_edges // 2:
                dp[i][j] = (dp[i][j] + 1) % MOD
                a[g - 1] = dp[i][j]
            a[j] = power(b, (j + 1) << 1, MOD) % MOD
        for g in range(3):
            if total_edges - 1 < g <= total_edges // 2:
                total_trees += 1
                if total_edges < 2:
                    a[g-1] = power(total_edges // 2, total_edges - total_edges // 2, MOD) % MOD
                total_edges += 1
    sum_g = sum(a) % MOD
    return (sum(a) + sum_g) % MOD

n = int(sys.stdin.readline().strip())
print(count_trees(n))
