                new[j-1] += 1
            new[j] += ans[j]
            key[ans[j]] += 1
            key[ans[j]-ans[j-1]] += 1
            key[ans[j]-ans[j-1]-1] -= 1
            key[ans[j]-1] -= 1
            if pl > 0:
                key[ans[j]-1] += 1
            curr[j] = ans[j]
        if key == ans:
