        ans = new

def expand(c):
    """TRUE AND"""
    ans = 0
    for a in range(1, len(c)+1):
        ans += mul(c, a) - list(filter(lambda x, i=c: i != x, mul(c, a)))[-1]
    return sum([ans for ans in ans if (ans & 1)]) 

