def find_min_points_to_delete(N, M, red_points, blue_points):
    """
    Find the minimum number of points to delete to ensure all remaining red points
    are on one side of the line and all remaining blue points are on the other side.
    """
    if can_form_line(red_points) and can_form_line(blue_points):
        return 0
    elif can_form_line(red_points) or can_form_line(blue_points):
        return min(N, M)
    else:
        return min(N, M) - 1

