            end = start + k - 1
            if end >= n:
                break

            # Initialize the current day's maximum tastiness
            cur_max = 0
            for i in range(start, end + 1):
                cur_max = max(cur_max, dp[i - 1][start - 1] + dp[i - 1][i])

            # Update the vector one step back
            dp[start][end] = cur_max

            # Iterate over every chef the current chef is able to copy from
            for chef in copy_abilities[start]:
                dp[start][end] = max(dp[start][end], dp[chef][start] + dp[start][ chef])

    results = []
    for query in queries:
        if query[0] == 1:
            l, r = query[1], query[2]
            operations = query[3] - query[1] + 1
            result = dp[l][r] % MOD
            if operations % 2 == 0:
                result += result + MOD
            if result >= MOD:
                result %= MOD
            results.append(result)
        else:
            i, x = query[1], query[2]
            new_a = dp[i][i] % MOD + x * ((1 << n) - 1)
            new_a %= MOD
            if new_a >= MOD:
                new_a %= MOD
            dp[i][i] = new_a

