class ImagePainter:
    """A class to simulate Anfisa's painting activity on a BerPaint by processing a sequence of canvas updates."""
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.total_colors = {}

    def _parse_input(self, input_segments, input_colors):
        self.n = len(input_segments)
        self.segments = []
        for segment in input_segments:
            x1, y1, x2, y2 = segment.split(' ')
            x1, y1, x2, y2 = map(int, [x1, y1, x2, y2])
            self.segments.append((x1, y1, x2, y2))

    def _get_intersection(self, p):
        """Calculates area of intersection between a point and segments."""
        intersections = []
        for seg, (xi, yi, xf, yf) in zip(self.single_row, self.segments):
            if ((xi >= p[0] and xi <= yf) or (xf >= p[0] and xf <= p[1])) and \
               ((yi >= p[0] and yi <= yf) or (yf >= p[0] and yf <= p[1])):
                xi_min, xf_max = sorted([xi, xf])
                yi_min, yf_max = sorted([yi, yf])
                area = (xf_max - xi_min) * (yf_max - yi_min)
                intersections.append((area, (xi_min, yi_min, xf_max, yf_max)))
        return intersections

    def _fill_image(self):
        """Fills the image based on the intersections resulting from points."""
        filled_areas = {}
        for color in self.single_row:
            self._get_intersection((len(self.single_row), 0))
        for (area, point) in self._get_intersection((self.width // 2, 0)):
            color_name = point[2].split('_')[1]
            if color_name in filled_areas:
                filled_areas[color_name] += area
            else:
                filled_areas[color_name] = area
        return filled_areas

