from functools import cache

def find_path():
    n = int(input())
    graphs = []
    for i in range(n):
        precyclei, cyclei = map(int, input().split())
        graphs.append((precyclei, cyclei))

    # Create a graph representation as a dictionary where each key is a vertex and its value is a list of its neighbors
    graph = {i: [] for i in range(n)}
    for vertex, values in graphs:
        if values != '?':
            graph[vertex].append(values)

    @cache
    def dfs(v, parent):
        code = []
        for nei in sorted(graph[v]):
            if nei != parent:
                new_code = dfs(nei, v)
                fib_arr = fibonacci_series(new_code[0], fib_series(v))
                for f in new_code[1:]:
                    for i in range(f):
                        code.append(fib_arr.pop(0))
                    code.append(0)
        return code

    def fibonacci_series(n, fib_series):
        curr = [0]
        prev = [1]
        for _ in range(n):
            curr, prev = curr + prev, curr
        fib_series.append(curr)
        assert(curr == 0)
        return fib_series[-1]

    def fib_series(n):
        return n if n <= 2 else fib_series(n-1) + fib_series(n-n%6)

    for j, _ in enumerate(graphs):
        code1, code2 = dfs(j, j), 0
        if len(code1) > len(graphs[0][1]) or len(code2) > len(graphs[0][1]):
            return "-1"
        for k in code1[:-1]:
            graphs[0][0] += k if k != 0 else 0
        for k in code1[-2:]:
            graphs[0][1] += k if k != 0 else 0
        t, m = graphs[0][0], graphs[0][1]
        fibs = fibonacci_series(t, fib_series(t))
        k = 1 + fibs.index(0) * 2 + m // 2
        fibs.pop()
        fibs.pop(0)
        fibs += fibs[0:-1] * m % 2
        for i, w in enumerate(graphs[0][1]):
            if w == '?':
                graphs[0][1][i] = fibs.pop(0)
    return ' '.join(map(str, graphs[0][1]))

