                y_centers = [y[0], y[1] % c - c]
                if y_centers[0] < -1 + c <= x_centers[0]:
                    dis = (x_centers[0] - y_centers[0]) ** 2 + (y_centers[1] - x_centers[1]) ** 2
                    centers.append((-dis + c) // 2)
        centers.sort()
        covered_regions = [[centers[0]]]
        # ..., add until you exhaust centers only
        excluded_centers = []
        for x in centers:
            x_center = [x[0], x[1] + c]
            new_covered = []
            for region in covered_regions:
                for x_point in region:
                    if not -1 - c <= x_point[0] <= -1 + c or 1 - c <= x_point[1] <= 1 + c:
                        new_covered.append([x_point[0]])
                    else:
                        if -c <= x_point[0] <= c or c <= x_point[1] <= 2 * c:
                            if any(all(min(n[0], x_point[0]) == n[1][0] for j in range(c)) or all(min(n[1], x_point[1]) == n[1][1] for j in range(c))
                                    for n in new_covered) and min(x_point[0], x_point[1]) - x_center[0][-1][-1] > x_center[0][0] - (x_point[0] - x_center[0][0]) // (params_square[0]['R'] + c) * params_square[1]['R']:
                            new_covered.append([x_point[0]])
                        else:
                            new_covered.append(region)
            if new_covered not in covered_regions and new_covered[0][0] not in excluded_centers:
                covered_regions.append(new_covered)
                excluded_centers.extend(set([e[0][0] for e in covered_regions if e[0][0] in x_center]))

    return check_monitored_area(covered_regions)
