import math
from collections import defaultdict

def calculate_damage(enemy_health, enemy_regen_rate, enemy_max_health):
    damage = 0
    max_health = enemy_max_health
    while max_health > 0:
        max_health -= enemy_health - max_health
        if max_health <= 0:
            break
        damage += min(enemy_health, max_health)
        enemy_health = max(min(enemy_health + enemy_regen_rate, enemy_max_health), enemy_health)
    return damage

def find_optimal_activation(second, enemies):
    gold = 0
    for enemy_id, enemy in enemies.items():
        health, regen, max_health = enemy.values()
        enemy_damage = calculate_damage(health, regen, max_health)
        gold += math.inf if enemy_damage > second else enemy_damage * second
    return gold

def primary_key_func(enemy_dict):
    return sorted(enemy_dict.keys(), key=lambda x: enemy_dict[x].values())

def solve():
    n, m = map(int, input().split())
    enemy_dict = defaultdict(list)
    for _ in range(n):
        health, regen, max_health = map(int, input().split())
        enemy_dict[max_health].append((health, regen, max_health))
    for _ in range(m):
        time, enemy_id, health = map(int, input().split())
        enemy_dict[time].append((100, health, 10))

    results = primary_key_func(enemy_dict)
    return max([find_optimal_activation(time, enemy_dict) for time, enemy_dict in enumerate(results)])

