from typing import List

def build_graph(n: int, directions: List[List[str]]) -> int:
    # Build an adjacency list representing the graph
    graph: List[List[tuple]] = [[] for _ in range(n)]
    for u, original_pos in reversed(directions):
        current_pos = original_pos
        for i in range(n):
            if graph[current_pos][2]:
                graph[current_pos][2] += graph[current_pos][1]
                if len(graph[current_pos]) == 2:
                    graph[current_pos] = [graph[current_pos][1], u, graph[current_pos][2]]  # Marking u as vertex with full cycle
                else:
                    graph[current_pos][2] = graph[current_pos][0] + 1  # Marking second position as the one in full cycle
            current_pos = graph[current_pos][0]
        if len(graph[current_pos]) == 1:  # Check cycle length for current_pos
            graph[current_pos] = [original_pos, u, current_pos]  # Add unmodified cycle to undirected pos

    # Check if the cycle length constraints are met for each vertex
    result: List[int] = []
    for i in range(n):
        pos = i
        cycle_length = 0
        for _ in range(n):
            graph[i][1] += graph[pos][1]
            if graph[i][0] == graph.__getitem__(cycle_length): 
                cycle_length += 1
            else:
                result.append(pos + 1)
                break
        else:
            result.append(-1)

    return result

n = int(input().strip())
directions = [tuple(map(int, input().strip().split())) for _ in range(n)]
print(" ".join(map(str, build_graph(n, directions))))
