def find_min_points_to_delete(red_points, blue_points):
    min_points = max(len(red_points), len(blue_points))
    removed_red = removed_blue = 0

    for y in range(max(red_points)[1], min(blue_points)[1] + 1):
        for point_y, point in enumerate(red_points):
            if point[1] != y:
                red_points[point_y] = (-1, point[0])
        for point_y, point in enumerate(blue_points):
            if point[1] != y:
                blue_points[point_y] = (-1, point[0])

        red_set = set((point[0], point[1]) for point in red_points)
        blue_set = set((point[0], point[1]) for point in blue_points)

        if len(red_set) == len(red_points) or len(blue_set) == 3:
            removed_red += 1
        if len(blue_set) == len(blue_points) or len(red_set) == 3:
            removed_blue += 1

        red_points = [(point[0], point[1]) for point in red_set if point != (-1, y)]
        blue_points = [(point[0], point[1]) for point in blue_set if point != (-1, y)]

    min_points -= min([removed_red, removed_blue])
    return min_points

